// ===== agenda-dinamica.js =====
function initDynamicAgenda(){
  const section = qs('#agenda');
  const list = qs('[data-agenda-list]', section || document);
  const status = qs('[data-agenda-sync-status]', section || document);
  if(!section || !list) return;

  const endpoint = (section.dataset.agendaApiUrl || '').trim();
  const configured = endpoint &&
    !endpoint.includes('COLE_AQUI') &&
    /^https:\/\/script\.google\.com\/macros\/s\/.+\/exec(?:\?.*)?$/.test(endpoint);

  if(!configured){
    if(status){
      status.innerHTML = '<i class="fa-solid fa-circle-info" aria-hidden="true"></i> Agenda exibida a partir da versão publicada no site. Configure a integração com o Google Sheets para atualização automática.';
    }
    return;
  }

  const create = (tag, className, text) => {
    const element = document.createElement(tag);
    if(className) element.className = className;
    if(text !== undefined && text !== null) element.textContent = text;
    return element;
  };

  const icon = className => {
    const element = document.createElement('i');
    element.className = className;
    element.setAttribute('aria-hidden', 'true');
    return element;
  };

  const appendMeta = (paragraph, iconClass, text) => {
    if(!text) return;
    if(paragraph.childNodes.length) paragraph.append(document.createTextNode('  '));
    paragraph.append(icon(iconClass), document.createTextNode(` ${text}`));
  };

  const renderItem = item => {
    const card = create('article', `agenda-card reveal is-visible${item.fixa ? ' agenda-card--fixed' : ''}`);

    let dateBox;
    if(item.fixa){
      dateBox = create('div', 'agenda-card__date agenda-card__date--fixed');
      dateBox.setAttribute('aria-hidden', 'true');
      dateBox.append(icon('fa-solid fa-repeat'), create('span', '', 'FIXA'));
    }else{
      dateBox = create('time', 'agenda-card__date');
      if(item.data) dateBox.setAttribute('datetime', item.data);
      dateBox.append(
        create('strong', '', item.dia || ''),
        create('span', '', item.mes || '')
      );
    }

    const content = create('div', 'agenda-card__content');

    if(item.fixa){
      const fixedLabel = create('span', 'agenda-card__fixed-label');
      fixedLabel.append(icon('fa-solid fa-thumbtack'), document.createTextNode(' Agenda fixa'));
      content.append(fixedLabel);
    }

    if(item.diaSemana || item.recorrencia){
      content.append(create(
        'span',
        'agenda-card__weekday',
        item.fixa ? (item.recorrencia || item.diaSemana) : item.diaSemana
      ));
    }

    content.append(create('h3', '', item.evento || 'Compromisso da campanha'));

    const meta = create('p');
    appendMeta(meta, 'fa-regular fa-clock', item.horario);
    appendMeta(meta, 'fa-solid fa-location-dot', item.local);
    if(meta.childNodes.length) content.append(meta);

    if(item.observacoes){
      content.append(create('p', 'agenda-card__notes', item.observacoes));
    }

    card.append(dateBox, content);
    return card;
  };

  const render = payload => {
    const items = Array.isArray(payload?.itens) ? payload.itens : [];

    if(!items.length){
      list.replaceChildren();
      const empty = create('div', 'agenda__empty');
      empty.append(
        icon('fa-regular fa-calendar'),
        create('strong', '', 'Novos compromissos serão divulgados em breve.'),
        create('span', '', 'A equipe da campanha está atualizando a agenda.')
      );
      list.append(empty);
    }else{
      const fragment = document.createDocumentFragment();
      items.forEach(item => fragment.append(renderItem(item)));
      list.replaceChildren(fragment);
    }

    if(status){
      const updated = payload?.ultimaAtualizacao
        ? ` Atualizada em ${payload.ultimaAtualizacao}.`
        : '';
      status.innerHTML = `<i class="fa-solid fa-circle-check" aria-hidden="true"></i> Agenda sincronizada automaticamente com a equipe da campanha.${updated}`;
      status.classList.add('is-synced');
    }

    try{
      localStorage.setItem('fabiano13007_agenda_cache', JSON.stringify({
        savedAt: Date.now(),
        payload
      }));
    }catch(_){}
  };

  const useCachedFallback = () => {
    try{
      const cached = JSON.parse(localStorage.getItem('fabiano13007_agenda_cache') || 'null');
      if(cached?.payload?.itens){
        render(cached.payload);
        if(status){
          status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Exibindo a última agenda sincronizada. A atualização online será tentada novamente no próximo acesso.';
          status.classList.remove('is-synced');
          status.classList.add('is-fallback');
        }
        return true;
      }
    }catch(_){}
    return false;
  };

  const callbackName = `fabianoAgenda_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  const script = document.createElement('script');
  let finished = false;

  const cleanup = () => {
    window.clearTimeout(timeout);
    script.remove();
    try{ delete window[callbackName]; }catch(_){ window[callbackName] = undefined; }
  };

  window[callbackName] = payload => {
    if(finished) return;
    finished = true;
    cleanup();

    if(payload?.ok === false){
      if(!useCachedFallback() && status){
        status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Não foi possível atualizar a agenda agora. Mantivemos a programação publicada no site.';
        status.classList.add('is-fallback');
      }
      return;
    }

    render(payload);
  };

  const separator = endpoint.includes('?') ? '&' : '?';
  script.src = `${endpoint}${separator}callback=${encodeURIComponent(callbackName)}&_=${Date.now()}`;
  script.async = true;
  script.onerror = () => {
    if(finished) return;
    finished = true;
    cleanup();
    if(!useCachedFallback() && status){
      status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> Não foi possível sincronizar a agenda agora. Mantivemos a programação publicada no site.';
      status.classList.add('is-fallback');
    }
  };

  const timeout = window.setTimeout(() => {
    if(finished) return;
    finished = true;
    cleanup();
    if(!useCachedFallback() && status){
      status.innerHTML = '<i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> A sincronização demorou além do esperado. Mantivemos a programação publicada no site.';
      status.classList.add('is-fallback');
    }
  }, 10000);

  document.head.append(script);
}




// ===== foto-apoiador.js =====
function initSupporterPhotoCreator(){
  const canvas=qs('#supporter-photo-canvas');
  const input=qs('#supporter-photo-input');
  const zoom=qs('#supporter-photo-zoom');
  const zoomValue=qs('#supporter-photo-zoom-value');
  const resetButton=qs('#supporter-photo-reset');
  const downloadButton=qs('#supporter-photo-download');
  const downloadLabel=qs('[data-supporter-download-label]');
  const empty=qs('#supporter-photo-empty');
  const stage=qs('[data-supporter-photo-stage]');
  const formatButtons=qsa('[data-supporter-format]');
  const formatNote=qs('#supporter-photo-format-note');
  const sharePanel=qs('#supporter-photo-share-panel');
  const shareButton=qs('#supporter-photo-share');
  const networkButtons=qsa('[data-supporter-network]');
  const shareStatus=qs('#supporter-photo-share-status');
  const editor=qs('.supporter-photo__editor');
  const controls=qs('.supporter-photo__controls');
  const zoomBlock=qs('[data-supporter-zoom]');
  const zoomDesktopAnchor=document.createComment('zoom-desktop-position');

  if(zoomBlock?.parentNode){
    zoomBlock.parentNode.insertBefore(zoomDesktopAnchor,zoomBlock);
  }

  const positionZoom=()=>{
    if(!zoomBlock||!editor||!controls)return;

    if(window.matchMedia('(max-width: 700px)').matches){
      // Mobile: immediately after the photo frame, before the hint,
      // privacy notice and "Escolher minha foto".
      stage.insertAdjacentElement('afterend',zoomBlock);
      zoomBlock.classList.add('supporter-photo__zoom--mobile-under-photo');
    }else{
      // Desktop: restore exactly to its original place among the controls.
      zoomDesktopAnchor.parentNode?.insertBefore(zoomBlock,zoomDesktopAnchor.nextSibling);
      zoomBlock.classList.remove('supporter-photo__zoom--mobile-under-photo');
    }
  };



  if(!canvas||!input||!zoom||!resetButton||!downloadButton||!stage)return;

  const ctx=canvas.getContext('2d');
  const photo=new Image();
  const campaignArt=new Image();
  campaignArt.src='data:image/png;base64,';

  const specs={
    profile:{width:1080,height:1080,filename:'eu-apoio-fabiano-13007-perfil.png'},
    feed:{width:1080,height:1350,filename:'eu-apoio-fabiano-13007-post-4x5.png'},
    story:{width:1080,height:1920,filename:'eu-apoio-fabiano-13007-story-9x16.png'}
  };

  let objectUrl='';
  let loaded=false;
  let outputFormat='feed';
  let baseScale=1,zoomFactor=1,offsetX=0,offsetY=0;
  let dragging=false,pointerId=null,lastX=0,lastY=0;

  const spec=()=>specs[outputFormat];
  const W=()=>canvas.width;
  const H=()=>canvas.height;

  const setCanvasSize=()=>{
    const s=spec();
    canvas.width=s.width;
    canvas.height=s.height;
    stage.dataset.outputFormat=outputFormat;
  };

  const clampOffsets=()=>{
    if(!loaded)return;
    const w=photo.naturalWidth*baseScale*zoomFactor;
    const h=photo.naturalHeight*baseScale*zoomFactor;
    offsetX=clamp(offsetX,-Math.max(0,(w-W())/2),Math.max(0,(w-W())/2));
    offsetY=clamp(offsetY,-Math.max(0,(h-H())/2),Math.max(0,(h-H())/2));
  };

  const drawCampaignArt=()=>{
    if(!(campaignArt.complete&&campaignArt.naturalWidth))return;
    const w=W(),h=H();
    const sx=0,sy=1122,sw=1800,sh=678;

    if(outputFormat==='profile'){
      const targetW=w*.78;
      const targetH=targetW*(sh/sw);
      const x=(w-targetW)/2;
      const y=h-targetH-w*.035;
      ctx.save();
      ctx.beginPath();
      ctx.arc(w/2,h/2,w*.49,0,Math.PI*2);
      ctx.clip();
      ctx.drawImage(campaignArt,sx,sy,sw,sh,x,y,targetW,targetH);
      ctx.restore();
    }else{
      const targetW=w;
      const targetH=targetW*(sh/sw);
      ctx.drawImage(campaignArt,sx,sy,sw,sh,0,h-targetH,targetW,targetH);
    }
  };

  const render=()=>{
    const w=W(),h=H();
    ctx.clearRect(0,0,w,h);

    if(!loaded){
      if(outputFormat==='profile'){
        ctx.save();
        ctx.beginPath();
        ctx.arc(w/2,h/2,w*.49,0,Math.PI*2);
        ctx.clip();
        ctx.fillStyle='#1B0E0D';
        ctx.fillRect(0,0,w,h);
        ctx.restore();
      }else{
        ctx.fillStyle='#1B0E0D';
        ctx.fillRect(0,0,w,h);
      }
      drawCampaignArt();
      return;
    }

    clampOffsets();
    const scale=baseScale*zoomFactor;
    const dw=photo.naturalWidth*scale;
    const dh=photo.naturalHeight*scale;
    const x=(w-dw)/2+offsetX;
    const y=(h-dh)/2+offsetY;

    if(outputFormat==='profile'){
      ctx.save();
      ctx.beginPath();
      ctx.arc(w/2,h/2,w*.49,0,Math.PI*2);
      ctx.clip();
      ctx.drawImage(photo,x,y,dw,dh);
      ctx.restore();
      drawCampaignArt();
    }else{
      ctx.drawImage(photo,x,y,dw,dh);
      drawCampaignArt();
    }
  };

  const resetView=()=>{
    if(!loaded)return;
    baseScale=Math.max(W()/photo.naturalWidth,H()/photo.naturalHeight);
    zoomFactor=1;offsetX=0;offsetY=0;
    zoom.value='100';
    if(zoomValue)zoomValue.value='100%';
    render();
  };

  const updateUi=()=>{
    formatButtons.forEach(b=>{
      const active=b.dataset.supporterFormat===outputFormat;
      b.classList.toggle('is-active',active);
      b.setAttribute('aria-pressed',String(active));
    });
    const social=outputFormat!=='profile';
    if(sharePanel)sharePanel.hidden=!social;
    stage.classList.toggle('is-circle',outputFormat==='profile');
    if(downloadLabel)downloadLabel.textContent='Baixar imagem';
    if(formatNote){
      formatNote.textContent=outputFormat==='profile'
        ?'Foto circular 1080×1080 para perfil. A imagem final contém apenas sua foto e a arte inferior da campanha.'
        :outputFormat==='feed'
          ?'Post vertical 1080×1350 (4:5), recomendado para o feed do Instagram. A imagem final contém apenas sua foto e a arte inferior da campanha.'
          :'Story vertical 1080×1920 (9:16). A imagem final contém apenas sua foto e a arte inferior da campanha.';
    }
    shareButton&&(shareButton.disabled=!loaded);
    networkButtons.forEach(b=>b.disabled=!loaded);
  };

  const setFormat=format=>{
    outputFormat=['feed','story'].includes(format)?format:'feed';
    setCanvasSize();
    updateUi();
    loaded?resetView():render();
  };

  const loadFile=file=>{
    if(!file)return;
    if(!/^image\/(jpeg|png|webp|heic|heif)$/i.test(file.type)&&!/\.(jpe?g|png|webp|heic|heif)$/i.test(file.name)){
      window.alert('Escolha uma imagem JPG, PNG, WEBP, HEIC ou HEIF.');input.value='';return;
    }
    if(file.size>25*1024*1024){window.alert('Escolha uma foto com até 25 MB.');input.value='';return;}
    if(objectUrl)URL.revokeObjectURL(objectUrl);
    objectUrl=URL.createObjectURL(file);
    photo.onload=()=>{
      loaded=true;
      empty?.classList.add('is-hidden');
      zoom.disabled=false;resetButton.disabled=false;downloadButton.disabled=false;
      updateUi();resetView();
    };
    photo.onerror=()=>{
      loaded=false;
      window.alert('Não foi possível abrir essa imagem. Tente JPG, PNG ou WEBP.');
      input.value='';
      render();
    };
    photo.src=objectUrl;
  };

  const blobFromCanvas=()=>new Promise((resolve,reject)=>{
    try{
      if(canvas.toBlob)canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('blob vazio')),'image/png',1);
      else fetch(canvas.toDataURL('image/png')).then(r=>r.blob()).then(resolve,reject);
    }catch(e){reject(e);}
  });

  const forceDownload=async()=>{
    render();
    try{
      const blob=await blobFromCanvas();
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a');
      a.href=url;a.download=spec().filename;a.style.display='none';
      document.body.append(a);a.click();a.remove();
      window.setTimeout(()=>URL.revokeObjectURL(url),4000);
      if(shareStatus)shareStatus.textContent='Imagem gerada e enviada para o fluxo de download do navegador.';
    }catch(error){
      console.error(error);
      try{
        const dataUrl=canvas.toDataURL('image/png');
        const a=document.createElement('a');a.href=dataUrl;a.download=spec().filename;
        document.body.append(a);a.click();a.remove();
      }catch(e){
        window.alert('Não foi possível gerar o arquivo da imagem. Recarregue a página e tente novamente.');
      }
    }
  };

  const shareGenerated=async preferredNetwork=>{
    render();
    const networkNames={instagram:'Instagram',facebook:'Facebook',x:'X',whatsapp:'WhatsApp'};
    try{
      const blob=await blobFromCanvas();
      const file=new File([blob],spec().filename,{type:'image/png'});
      if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[file]}))){
        if(shareStatus)shareStatus.textContent=preferredNetwork?`Escolha ${networkNames[preferredNetwork]} na tela de compartilhamento.`:'Escolha a rede social na tela de compartilhamento.';
        await navigator.share({files:[file],title:'Eu apoio Fabiano Trompetista 13007',text:'Eu apoio Fabiano Trompetista para Deputado Distrital — 13007.'});
        return;
      }
      await forceDownload();
      if(shareStatus)shareStatus.textContent='Seu navegador não permite anexar a imagem diretamente. A imagem foi baixada para você publicar normalmente.';
    }catch(error){
      if(error?.name!=='AbortError')console.error(error);
    }
  };

  formatButtons.forEach(b=>b.addEventListener('click',()=>setFormat(b.dataset.supporterFormat)));
  input.addEventListener('change',()=>loadFile(input.files?.[0]));
  zoom.addEventListener('input',()=>{
    if(!loaded)return;
    zoomFactor=Number(zoom.value)/100;
    if(zoomValue)zoomValue.value=`${zoom.value}%`;
    clampOffsets();render();
  });
  resetButton.addEventListener('click',resetView);
  downloadButton.addEventListener('click',forceDownload);
  shareButton?.addEventListener('click',()=>shareGenerated());
  networkButtons.forEach(b=>b.addEventListener('click',()=>shareGenerated(b.dataset.supporterNetwork)));

  stage.addEventListener('pointerdown',e=>{
    if(!loaded)return;
    dragging=true;pointerId=e.pointerId;lastX=e.clientX;lastY=e.clientY;
    stage.classList.add('is-dragging');stage.setPointerCapture?.(pointerId);e.preventDefault();
  });
  stage.addEventListener('pointermove',e=>{
    if(!dragging||e.pointerId!==pointerId||!loaded)return;
    const r=stage.getBoundingClientRect();
    offsetX+=(e.clientX-lastX)*(W()/r.width);
    offsetY+=(e.clientY-lastY)*(H()/r.height);
    lastX=e.clientX;lastY=e.clientY;
    clampOffsets();render();e.preventDefault();
  });
  const end=e=>{
    if(!dragging)return;
    if(e?.pointerId!==undefined&&pointerId!==null&&e.pointerId!==pointerId)return;
    dragging=false;stage.classList.remove('is-dragging');
    try{stage.releasePointerCapture?.(pointerId)}catch(_){}
    pointerId=null;
  };
  stage.addEventListener('pointerup',end);
  stage.addEventListener('pointercancel',end);
  stage.addEventListener('lostpointercapture',end);

  campaignArt.onload=render;
  window.addEventListener('beforeunload',()=>{if(objectUrl)URL.revokeObjectURL(objectUrl)},{once:true});

  positionZoom();
  setCanvasSize();
  updateUi();
  render();

  let zoomPositionTimer;
  window.addEventListener('resize',()=>{
    clearTimeout(zoomPositionTimer);
    zoomPositionTimer=setTimeout(positionZoom,100);
  });

}

// ===== app.js =====
function initLazyImages() {
  qsa('img[loading="lazy"]').forEach(image => {
    image.classList.add('lazy-image');
    const loaded = () => image.classList.add('is-loaded');
    image.complete ? loaded() : image.addEventListener('load', loaded, { once: true });
  });
}

function initApp() {
  initLoader();
  initNavbar();
  initScroll();
  initReveal();
  initCounters();
  initHero();
  initHeroVideoPlaylist();
  const lightbox = initLightbox();
  initGallery(lightbox.open);
  initLazyImages();
  initWhatsappFloatText();
  initVoterNote();
  initSupporterPhotoCreator();
  initMediaAuthenticityNotice();
  initCampaignPhotosCarousel();
  initLulaCarousels();
  initAboutCarousel();
  initDynamicAgenda();
  const year = qs('#current-year');
  if (year) year.textContent = String(new Date().getFullYear());
}

document.readyState === 'loading'
  ? document.addEventListener('DOMContentLoaded', initApp, { once: true })
  : initApp();
